package com.tapeverify.copilot.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.fasterxml.jackson.databind.ObjectMapper; import com.tapeverify.copilot.entity.*; import com.tapeverify.copilot.repository.LoanRepository; import java.math.*; import java.time.*; import java.util.List; import org.junit.jupiter.api.*;
class ValidationServiceImplTest { private ValidationService service; @BeforeEach void setup(){ValidationRules rules=new ValidationRules(new ObjectMapper());rules.load();LoanRepository repo=mock(LoanRepository.class);when(repo.findBySourceLoanId(any())).thenReturn(List.of());when(repo.findByBorrowerNameAndPrincipalAmountAndOriginationDate(any(),any(),any())).thenReturn(List.of());service=new ValidationServiceImpl(repo,rules);} @Test void reportsAllConfiguredValidationRules(){Loan loan=Loan.builder().batchId("b").sourceLoanId("L1").documentStatus("AVAILABLE").paymentStatus("CURRENT").currentBalance(BigDecimal.ZERO).lastUpdatedAt(LocalDateTime.now()).principalAmount(BigDecimal.ZERO).interestRate(new BigDecimal("31")).originationDate(LocalDate.of(2025,1,2)).maturityDate(LocalDate.of(2025,1,1)).status(LoanStatus.PENDING).sha256Hash("x").createdAt(LocalDateTime.now()).build();var errors=service.validate(loan);assertTrue(errors.stream().anyMatch(e->e.getFieldName().equals("borrowerName")));assertTrue(errors.stream().anyMatch(e->e.getFieldName().equals("principalAmount")));assertTrue(errors.stream().anyMatch(e->e.getFieldName().equals("interestRate")));assertTrue(errors.stream().anyMatch(e->e.getErrorMessage().contains("Maturity")));}}
